package com.flippingfriend.companion;
import org.junit.Test; import static org.junit.Assert.*;
public class BuyReplacementCalibratedDurationEvaluatorTest {
 @Test public void appliesProductionWaitOnlyFormulaInOrder(){BuyReplacementDurationCalibrationInputContext s=context();BuyReplacementCalibratedDurationEvaluationSet r=new BuyReplacementCalibratedDurationEvaluator().evaluate(s,1100);assertNotNull(r);assertEquals(s.getEvaluations().size(),r.getEvaluations().size());for(int i=0;i<r.getEvaluations().size();i++){BuyReplacementRoundTripCompletionEvaluation a=s.getEvaluations().get(i);BuyReplacementCalibratedDurationEvaluation e=r.getEvaluations().get(i);assertEquals(correct(a.getBuyExpectedHours(),a.getBuyWaitHours(),s.getWaitMultiplier()),e.getCalibratedBuyHours(),0.0);assertEquals(correct(a.getSellExpectedHours(),a.getSellWaitHours(),s.getWaitMultiplier()),e.getCalibratedSellHours(),0.0);assertEquals(a.getSellOffsetIndex(),e.getSellOffsetIndex());}try{r.getEvaluations().clear();fail("immutable");}catch(UnsupportedOperationException expected){}}
 @Test public void unavailableAndStaleInputsFailClosed(){BuyReplacementCalibratedDurationEvaluator e=new BuyReplacementCalibratedDurationEvaluator();assertNull(e.evaluate(null,1100));assertNull(e.evaluate(context(),1221));}
 @Test public void contractsCarryNoSlotEconomicsRankingSelectionOrAuthorization()throws Exception{for(String f:new String[]{"BuyReplacementCalibratedDurationEvaluation.java","BuyReplacementCalibratedDurationEvaluationSet.java"}){String s=java.nio.file.Files.readString(java.nio.file.Path.of("src/main/java/com/flippingfriend/companion/"+f));for(String x:new String[]{"expectedSlotHours","expectedProfit","unwindLoss","worstLoss","kelly","expectedGpPerSlotHour","selected","score","rank","PortfolioCandidate","PolicyDecision","OfferLifecycleAction","REPLACEMENT_AUTHORIZED"})assertFalse(s.contains(x));}}
 private static double correct(double h,double w,double m){return w<=0||Double.isNaN(w)||Double.isInfinite(w)?h:w*m+Math.max(0,h-w);} private static BuyReplacementDurationCalibrationInputContext context(){return BuyReplacementDurationCalibrationInputContextComposerTest.contextForCompanionTests();}
}
